order_confirmation.bodyHtml:
{% assign buyer_email_rtl = false %}{% if locale_direction == 'rtl' %}{% assign buyer_email_rtl = true %}{% endif %}{% assign delivery_method_types = delivery_agreements | map: 'delivery_method_type' | uniq %}
{% assign has_split_cart = false %}
{% assign non_none_count = 0 %}
{% for type in delivery_method_types %}
  {% unless type == 'none' %}
    {% assign non_none_count = non_none_count | plus: 1 %}
  {% endunless %}
{% endfor %}
{% if non_none_count > 1 %}
  {% assign has_split_cart = true %}
{% endif %}

{% assign non_none_agreements_count = 0 %}
{% for agreement in delivery_agreements %}
  {% unless agreement.delivery_method_type == 'none' %}
    {% assign non_none_agreements_count = non_none_agreements_count | plus: 1 %}
  {% endunless %}
{% endfor %}

{% capture email_title %}
  Thank you for your order!
{% endcapture %}
{% capture email_body %}
  {% if has_pending_payment %}
    {% if buyer_action_required %}
      You’ll get a confirmation email after completing your payment.
    {% else %}
      Your payment is being processed. You'll get an email when your order is confirmed.
    {% endif %}
  {% elsif payment_charged_on_fulfillment %}
    Hi {% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ customer.first_name }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}, we received your order. Your payment method will be charged when your order is ready to be fulfilled. We'll notify you when it's on its way.
  {% else %}
    {% if requires_shipping %}
      {% if has_split_cart %}
        {% case split_cart_delivery_method %}
          {% when 'pick-up' %}
            You’ll receive an email when your order is ready for pickup.
          {% when 'local' %}
            Hi {% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ customer.first_name }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}, we're getting your order ready for delivery.
          {% when 'shipping' %}
            We're getting your order ready to be shipped. We will notify you when it has been sent.
          {% else %}
            We're getting your order ready to be shipped. We will notify you when it has been sent.
        {% endcase %}
      {% else %}
        {% case delivery_method %}
          {% when 'pick-up' %}
            You’ll receive an email when your order is ready for pickup.
          {% when 'local' %}
            Hi {% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ customer.first_name }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}, we're getting your order ready for delivery.
          {% else %}
            We're getting your order ready to be shipped. We will notify you when it has been sent.
        {% endcase %}
      {% endif %}
        {% if delivery_instructions != blank  %}
          <p><b>Delivery information:</b> {% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ delivery_instructions }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}</p>
        {% endif %}
      {% unless delivery_method_types.size > 1 %}
        {% if consolidated_estimated_delivery_time %}
          {% if non_none_agreements_count > 1 %}
            <h3 class="estimated_delivery__title">Estimated delivery</h3>
            <p>{% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ consolidated_estimated_delivery_time }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}</p>
          {% else %}
            <p>
              Estimated delivery <b>{% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ consolidated_estimated_delivery_time }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}</b>
            </p>
          {% endif %}
        {% endif %}
      {% endunless %}
    {% endif %}
  {% endif %}
  {% assign gift_card_line_items = line_items | where: "gift_card" %}
  {% assign found_gift_card_with_recipient_email = false %}
  {% for line_item in gift_card_line_items %}
    {% if line_item.properties["__shopify_send_gift_card_to_recipient"] and line_item.properties["Recipient email"] %}
      {% assign found_gift_card_with_recipient_email = true %}
      {% break %}
    {% endif %}
  {% endfor %}
  {% if found_gift_card_with_recipient_email %}
    <p>Your gift card recipient will receive an email with their gift card code.</p>
  {% elsif gift_card_line_items.first %}
    <p>You’ll receive separate emails for any gift cards.</p>
  {% endif %}
{% endcapture %}

<!DOCTYPE html>
<html lang="en"{% if buyer_email_rtl %} dir="rtl"{% endif %}>
  <head>
  <title>{{ email_title }}</title>
  <meta http-equiv="Content-Type" content="text/html; charset=utf-8">
  <meta name="viewport" content="width=device-width">
  <link rel="stylesheet" type="text/css" href="/assets/notifications/styles.css">
  <style>
    body, .body { background-color: #fcf8f2 !important; margin: 0; }
    .body, .container, td, p, h1, h2, h3, h4, span, a, li, label, .shop-name__text { font-family: Arial, Helvetica, sans-serif; }
    .body, .container, td, p, li { color: #2a0d12; }
    .header__cell, .content__cell, .section__cell, .footer__cell, .row, .container { background-color: #fcf8f2 !important; }
    .header__cell { padding: 28px 0 18px !important; border-bottom: 1px solid #e0d3cf; }
    .footer__cell { background-color: #551c25 !important; padding: 26px 0 !important; border-top: 0 !important; }
    h2, .section__title, .subtotal-table__title, .order-list__item-title, .customer-info__item-title { font-family: Georgia, 'Times New Roman', serif; font-weight: normal; }
    h2 { color: #551c25 !important; font-size: 26px !important; line-height: 1.25; margin: 0 0 12px; }
    h3, h4, .section__title, .subtotal-table__title, .customer-info__item-title { color: #551c25 !important; }
    h3 { font-family: Arial, Helvetica, sans-serif; font-size: 11px !important; letter-spacing: 2px; text-transform: uppercase; color: #8a6a6f !important; font-weight: normal; }
    p { font-size: 14px; line-height: 1.7; color: #4a3338; }
    a, a:hover, a:active, a:visited, .link, .link__text { color: #551c25 !important; }
    .button__cell, .actions-buttons .button__cell--primary, .button__cell--primary { background: #595b33 !important; background-color: #595b33 !important; border-radius: 0 !important; border: 0 !important; }
    .button__text, .button__text:hover, .button__text:active, .button__text:visited { color: #ffffff !important; font-size: 12px !important; letter-spacing: 2px; text-transform: uppercase; padding: 16px 26px !important; }
    .actions-buttons .button__cell--outlined { background: transparent !important; border: 1px solid #551c25 !important; border-radius: 0 !important; }
    .actions-buttons .button__cell--outlined .button__text { color: #551c25 !important; }
    .link__cell, .link__cell a { color: #551c25 !important; text-decoration: underline; }
    .order-list__item, .subtotal-table, .subtotal-lines, .section, .customer-info { border-color: #e0d3cf !important; }
    .order-list__item { border-bottom: 1px solid #e0d3cf !important; }
    .order-list__product-image { border-radius: 0 !important; border: 0 !important; background: #f1eeea; }
    .order-list__item-title { font-family: Arial, Helvetica, sans-serif; color: #2a0d12 !important; font-size: 14px !important; font-weight: normal !important; }
    .order-list__item-variant, .order-list__item-property, .order-list__unit-price, .order-list__item-discount-allocation { color: #8a6a6f !important; font-size: 12px !important; }
    .order-list__item-price, .subtotal-line__value { color: #2a0d12 !important; font-size: 14px !important; }
    .subtotal-line__title, .subtotal-line__title p { color: #4a3338 !important; font-size: 13px !important; }
    .subtotal-table--total td, .subtotal-table--total .subtotal-line__title p, .subtotal-table--total .subtotal-line__value { color: #551c25 !important; font-size: 16px !important; font-weight: normal !important; }
    .subtotal-table--total { border-top: 1px solid #e0d3cf !important; }
    .subtotal-line__value-small, .total-discount--amount, .disclaimer__subtext, .small { color: #8a6a6f !important; }
    .customer-info__item, .address, .customer-info__item-content { color: #4a3338 !important; font-size: 13px; line-height: 1.6; }
    .vertical-line, .curved-line-cell-container { border-color: #e0d3cf !important; }
    .discount-tag-icon { display: none; }
    .od-footer { background: #551c25; color: #e5d9c7; text-align: center; padding: 26px 36px; font-size: 12px; line-height: 1.9; letter-spacing: 1px; font-family: Georgia, 'Times New Roman', serif; }
    .od-footer a { color: #e5d9c7 !important; text-decoration: none; font-size: 12px !important; font-family: Georgia, 'Times New Roman', serif; }
    .od-footer .od-footer__links a { font-size: 13px !important; letter-spacing: 3px; }
    .od-footer .od-footer__links a { text-transform: uppercase; }
    .od-footer__muted { color: #d9c9b8; letter-spacing: 0; }
    .od-outline { border: 1px solid #551c25 !important; border-radius: 0 !important; padding: 0 !important; }
    .od-outline .od-outline__text, .od-outline .od-outline__text:hover, .od-outline .od-outline__text:visited { display: block; color: #551c25 !important; font-size: 12px !important; letter-spacing: 2px; text-transform: uppercase; padding: 15px 26px !important; text-decoration: none !important; }
    .secondary-action-cell { margin-top: 0 !important; }
    .od-header__logo { display: block; margin: 0 auto; }
    .order-number__text, .po-number__text { color: #551c25 !important; font-size: 12px !important; letter-spacing: 2px; text-transform: uppercase; }
    .order-number__cell { vertical-align: middle; }
  </style>
</head>

  <body>
    <table class="body{% if buyer_email_rtl %} buyer-email-rtl{% endif %}"{% if buyer_email_rtl %} dir="rtl"{% endif %}>
      <tr>
        <td>
          <table class="header row">
  <tr>
    <td class="header__cell">
      <center>

        <table class="container"{% if buyer_email_rtl == true %} dir="rtl"{% endif %}>
          <tr>
            <td>

              <table class="row">
                <tr>
                  <td class="shop-name__cell"{% if buyer_email_rtl == true %} align="right"{% endif %}>
                    <a href="{{ shop.url }}" style="text-decoration:none;"><img src="https://cdn.shopify.com/s/files/1/0996/6338/0850/files/Omarieden-Logos-_-Icons-_1_-_1.png?v=1792310589" alt="{{ shop.name }}" width="180" style="width:180px; height:auto; display:block;"></a>
                  </td>

                    <td{% if buyer_email_rtl == true %} class="order-po-number__cell"{% endif %}>
                      <table class="order-po-number__container">
                        <tr>
                          <td class="order-number__cell"{% if buyer_email_rtl == true %} align="left"{% endif %}>
                            <span class="order-number__text">
                              Order {% if buyer_email_rtl == true %}<span dir="ltr" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ order_name }}{% if buyer_email_rtl == true %}</span>{% endif %}
                            </span>
                          </td>
                        </tr>
                        {%- if po_number %}
                            <tr>
                              <td class="po-number__cell"{% if buyer_email_rtl == true %} align="left"{% endif %}>
                                <span class="po-number__text">
                                  PO number {% if buyer_email_rtl == true %}<span dir="ltr" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}#{{ po_number }}{% if buyer_email_rtl == true %}</span>{% endif %}
                                </span>
                              </td>
                            </tr>
                        {%- endif %}
                      </table>
                    </td>
                </tr>
              </table>

            </td>
          </tr>
        </table>

      </center>
    </td>
  </tr>
</table>

          <table class="row content">
  <tr>
    <td class="content__cell">
      <center>
        <table class="container"{% if buyer_email_rtl == true %} dir="rtl"{% endif %}>
          <tr>
            <td>

            <h2>{{ email_title }}</h2>
            <p>{{ email_body }}</p>
            {% assign transaction_count = transactions | size %}
  {% if transaction_count > 0 %}
    {% for transaction in transactions %}
      {% if transaction.show_buyer_pending_payment_instructions? %}
        <p> {% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{transaction.buyer_pending_payment_notice}}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %} </p>
        <p>
        <table class="row">
          <tr>
            {% for instruction in transaction.buyer_pending_payment_instructions %}
              <td>{% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ instruction.header }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}</td>
            {% endfor %}
            <td>Amount</td>
          </tr>
          <tr>
            {% for instruction in transaction.buyer_pending_payment_instructions %}
              <td>{% if buyer_email_rtl == true %}<span dir="ltr" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ instruction.value }}{% if buyer_email_rtl == true %}</span>{% endif %}</td>
            {% endfor %}
            <td>{% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{transaction.amount | money}}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}</td>
          </tr>
        </table>
        </p>
      {% endif %}
    {% endfor%}
  {% endif %}

            {% if order_status_url %}
              {% if false %}
                {% if shop_app_tracking_button_variant_key == "track_with_shop" %}
                <table class="row actions">
  <tr>
    <td class="empty-line">&nbsp;</td>
  </tr>
  <tr>
    <td class="actions__cell">
      {% capture shop_logo_img %}<img src="{{ 'mailer/shop_logo.png' | cdn_asset_url }}" alt="Shop" width="42" height="17" class="button__shop-logo">{% endcapture %}
      <table class="actions-buttons" width="100%" cellpadding="0" cellspacing="0" border="0">
        <tr>
          <td class="button__cell button__cell--primary" width="50%">
            <a href="{{ order_status_url }}" class="button__text">View your order</a>
          </td>
          <td class="button__cell--separator"></td>
