            <p>{% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ custom_message }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}</p>
