        {% if buyer_email_rtl == true %}<span dir="{% if property.first == 'Recipient email' %}ltr{% else %}auto{% endif %}" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ property.last }}{% if buyer_email_rtl == true %}</span>{% endif %}
      {% endif %}
      </dd>
    </div>
  {% endif %}
