    {% when 'fraud' %}
      Order {% if buyer_email_rtl == true %}<span dir="ltr" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ name }}{% if buyer_email_rtl == true %}</span>{% endif %} was canceled because of unforeseen circumstances and your payment has not yet been refunded.
    {% when 'declined' %}
