            </td>
          </tr>
        </table>

      </center>
    </td>
  </tr>
</table>

          <table class="row content">
  <tr>
    <td class="content__cell">
      <center>
        <table class="container"{% if buyer_email_rtl == true %} dir="rtl"{% endif %}>
          <tr>
            <td>

            {% if payment_schedule.overdue? and payment_schedule.number_of_days_overdue == 0 %}
              <h2>Your payment is due today</h2>
            {% elsif payment_schedule.due_later? and payment_schedule.due_in_days == 0 %}
              <h2>Your payment is due today</h2>
            {% elsif payment_schedule.overdue? and payment_schedule.number_of_days_overdue == 1 %}
              <h2>Your payment was due yesterday</h2>
            {% elsif payment_schedule.due_later? and payment_schedule.due_in_days == 1 %}
              <h2>Your payment is due tomorrow</h2>
            {% elsif payment_schedule.due_later? and payment_schedule.due_in_days > 1 %}
              <h2>Your payment is due in {% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ payment_schedule.due_in_days}}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %} days</h2>
            {% else %}
              <h2>Your payment is {% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ payment_schedule.number_of_days_overdue }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %} days overdue</h2>
