                </p>
              {% else %}
                <p>
                  This is a reminder that your payment of {% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ payment_schedule.amount_due | money_with_currency }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %} for order {% if buyer_email_rtl == true %}<span dir="ltr" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ name }}{% if buyer_email_rtl == true %}</span>{% endif %} was due on {% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ payment_schedule.due_at | date: '%B %e, %Y' }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}.

                </p>
              {% endif %}
              <p>
                Thank you.
              </p>
            {% endif %}
            {% if checkout_payment_collection_url %}
              <table class="row actions">
  <tr>
    <td class="actions__cell">
      <table class="button main-action-cell">
        <tr>
          <td class="button__cell"><a href="{{ checkout_payment_collection_url }}" class="button__text">Pay now</a></td>
        </tr>
      </table>
    </td>
  </tr>
</table>

            {% endif %}

            </td>
          </tr>
        </table>
      </center>
    </td>
  </tr>
</table>
        <table class="row footer">
  <tr>
    <td class="footer__cell">
      <center>
        <table class="container"{% if buyer_email_rtl == true %} dir="rtl"{% endif %}>
          <tr>
            <td class="od-footer" style="background:#551c25; color:#e5d9c7; text-align:center; padding:0 20px; font-family:Georgia,'Times New Roman',serif; font-size:12px; line-height:1.9; letter-spacing:1px;">
              <div class="od-footer__links" style="margin-bottom:6px;">
                <a href="https://www.instagram.com/omarieden" style="color:#e5d9c7; text-decoration:none; text-transform:uppercase; font-size:13px; letter-spacing:3px; font-family:Georgia,'Times New Roman',serif;">Instagram</a>
                &nbsp;&nbsp;&middot;&nbsp;&nbsp;
                <a href="https://www.tiktok.com/@omarieden" style="color:#e5d9c7; text-decoration:none; text-transform:uppercase; font-size:13px; letter-spacing:3px; font-family:Georgia,'Times New Roman',serif;">TikTok</a>
                &nbsp;&nbsp;&middot;&nbsp;&nbsp;
                <a href="https://wa.me/" style="color:#e5d9c7; text-decoration:none; text-transform:uppercase; font-size:13px; letter-spacing:3px; font-family:Georgia,'Times New Roman',serif;">WhatsApp</a>
              </div>
              <div class="od-footer__muted" style="color:#d9c9b8; letter-spacing:0; font-style:italic; margin-top:12px;">{{ shop.name }}, Al Khobar, Saudi Arabia &middot; <a href="{{ shop.url }}" style="color:#d9c9b8; text-decoration:none; font-size:12px;">omarieden.com</a></div>
              <div class="od-footer__muted" style="color:#d9c9b8; letter-spacing:0; margin-top:4px;">Questions? Reply to this email or write to <a href="mailto:support@omarieden.com" style="color:#e5d9c7; text-decoration:underline; font-size:12px;">support@omarieden.com</a><!-- shopify-shop-marketplace-footer --></div>
            </td>
          </tr>
        </table>
      </center>
    </td>
  </tr>
</table>

<img src="{{ 'notifications/spacer.png' | shopify_asset_url }}" class="spacer" height="1" />

      </td>
    </tr>
  </table>
</body>
</html>

