    .order-list__item-variant, .order-list__item-property, .order-list__unit-price, .order-list__item-discount-allocation { color: #8a6a6f !important; font-size: 12px !important; }
    .order-list__item-price, .subtotal-line__value { color: #2a0d12 !important; font-size: 14px !important; }
    .subtotal-line__title, .subtotal-line__title p { color: #4a3338 !important; font-size: 13px !important; }
    .subtotal-table--total td, .subtotal-table--total .subtotal-line__title p, .subtotal-table--total .subtotal-line__value { color: #551c25 !important; font-size: 16px !important; font-weight: normal !important; }
    .subtotal-table--total { border-top: 1px solid #e0d3cf !important; }
    .subtotal-line__value-small, .total-discount--amount, .disclaimer__subtext, .small { color: #8a6a6f !important; }
    .customer-info__item, .address, .customer-info__item-content { color: #4a3338 !important; font-size: 13px; line-height: 1.6; }
    .vertical-line, .curved-line-cell-container { border-color: #e0d3cf !important; }
    .discount-tag-icon { display: none; }
    .od-footer { background: #551c25; color: #e5d9c7; text-align: center; padding: 26px 36px; font-size: 12px; line-height: 1.9; letter-spacing: 1px; font-family: Georgia, 'Times New Roman', serif; }
    .od-footer a { color: #e5d9c7 !important; text-decoration: none; font-size: 12px !important; font-family: Georgia, 'Times New Roman', serif; }
    .od-footer .od-footer__links a { font-size: 13px !important; letter-spacing: 3px; }
    .od-footer .od-footer__links a { text-transform: uppercase; }
    .od-footer__muted { color: #d9c9b8; letter-spacing: 0; }
    .od-outline { border: 1px solid #551c25 !important; border-radius: 0 !important; padding: 0 !important; }
    .od-outline .od-outline__text, .od-outline .od-outline__text:hover, .od-outline .od-outline__text:visited { display: block; color: #551c25 !important; font-size: 12px !important; letter-spacing: 2px; text-transform: uppercase; padding: 15px 26px !important; text-decoration: none !important; }
    .secondary-action-cell { margin-top: 0 !important; }
    .od-header__logo { display: block; margin: 0 auto; }
    .order-number__text, .po-number__text { color: #551c25 !important; font-size: 12px !important; letter-spacing: 2px; text-transform: uppercase; }
    .order-number__cell { vertical-align: middle; }
  </style>
</head>

  <body>
    <table class="body{% if buyer_email_rtl %} buyer-email-rtl{% endif %}"{% if buyer_email_rtl %} dir="rtl"{% endif %}>
      <tr>
        <td>
          <table class="header row">
  <tr>
    <td class="header__cell">
      <center>
        <table class="container">
          <tr>
            <td>

              <table class="row">
                <tr>
                  <td class="shop-name__cell">
                    <a href="{{ shop.url }}" style="text-decoration:none;"><img src="https://cdn.shopify.com/s/files/1/0996/6338/0850/files/Omarieden-Logos-_-Icons-_1_-_1.png?v=1792310589" alt="{{ shop.name }}" width="180" style="width:180px; height:auto; display:block;"></a>
                  </td>

                  <td class="order-number__cell">
                    <span class="order-number__text">
                      {% if buyer_email_rtl == true %}<span dir="ltr" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ draft_order.name }}{% if buyer_email_rtl == true %}</span>{% endif %}
                    </span>
                  </td>
                </tr>
              </table>
            </td>
          </tr>
        </table>
      </center>
    </td>
  </tr>
</table>


          <table class="row content">
  <tr>
    <td class="content__cell">
      <center>
        <table class="container">
          <tr>
            <td>

            <h2>{{ email_title }}</h2>

            <table class="row actions">
  <tr>
    <td class="empty-line">&nbsp;</td>
  </tr>
  <tr>
    <td class="actions__cell">
      <table class="button main-action-cell">
        <tr>
          <td class="button__cell"><a href="{{ checkout_url }}" class="button__text">Continue to checkout</a></td>
        </tr>
      </table>

      <table class="link secondary-action-cell">
        <tr>
          <td class="link__cell">
            or <a href="{{ shop.url }}">Visit our store</a>
          </td>
        </tr>
      </table>
    </td>
  </tr>
</table>


            {% if custom_message != blank %}
              <br>
              <p style="font-weight: normal; color: #000;">{% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ custom_message }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}</p>
            {% endif %}

            </td>
          </tr>
        </table>
      </center>
    </td>
  </tr>
</table>

          <table class="row section top-border">
  <tr>
    <td class="section__cell">
      <center>
        <table class="container">
          <tr>
            <td>
              <h3>Order summary</h3>
            </td>
          </tr>
        </table>
        <table class="container">
          <tr>
            <td>

            <table class="row">
  {% for line in subtotal_line_items %}
    <tr class="order-list__item">
      <td class="order-list__item__cell">
        <table>
          <td
            {% if line.bundle_parent? %}
              class="order-list__parent-image-cell"
            {% else %}
              class="order-list__image-cell"
            {% endif %}
          >
            {% if line.image %}
              <img
                src="{{ line | img_url: 'compact_cropped' }}"
                align="{% if buyer_email_rtl == true %}right{% else %}left{% endif %}"
                width="60"
                height="60"
                class="order-list__product-image"
              />
            {% else %}
              <div class="order-list__no-image-cell">
                <img
                  src="{{ 'notifications/no-image.png' | shopify_asset_url }}"
                  align="{% if buyer_email_rtl == true %}right{% else %}left{% endif %}"
                  width="60"
                  height="60"
                  class="order-list__no-product-image"
                />
              </div>
            {% endif %}
          </td>

          <td class="order-list__product-description-cell">
            {% if line.product.title %}
              {% assign line_title = line.product.title %}
            {% else %}
              {% assign line_title = line.title %}
            {% endif %}

            {% assign line_display = line.quantity  %}

            <span class="order-list__item-title">
              {% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ line_title }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}&nbsp;&times;&nbsp;{% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ line_display }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}
            </span>
            <br/>

            {% if line.variant.title != blank and line.variant.title != 'Default Title' %}
              <span class="order-list__item-variant">
                {% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ line.variant.title }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}
              </span>
              <br/>
            {% endif %}

              {% for component in line.bundle_components %}
                <table>
                  <tr class="order-list__item">
                    <td class="order-list__bundle-item">
                      <table>
                        <td class="order-list__image-cell">
                          {% if component.image %}
                            <img
                              src="{{ component | img_url: 'compact_cropped' }}"
                              align="{% if buyer_email_rtl == true %}right{% else %}left{% endif %}"
                              width="40"
                              height="40"
                              class="order-list__product-image"
                            />
                          {% else %}
                            <div class="order-list__no-image-cell small">
                              <img
                                src="{{ 'notifications/no-image.png' | shopify_asset_url }}"
                                align="{% if buyer_email_rtl == true %}right{% else %}left{% endif %}"
                                width="40"
                                height="40"
                                class="order-list__no-product-image small"
                              />
                            </div>
                          {% endif %}
                        </td>
                        <td class="order-list__product-description-cell">
                          {% if component.product.title %}
                            {% assign component_title = component.product.title %}
                          {% else %}
                            {% assign component_title = component.title %}
                          {% endif %}

                          {% assign component_display = component.quantity %}

                          <span class="order-list__item-title">{% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ component_display }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}&nbsp;&times;&nbsp;{% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ component_title }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}</span><br>

                          {% if component.variant.title != 'Default Title'%}
                            <span class="order-list__item-variant">{% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ component.variant.title }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}</span>
                          {% endif %}
                        </td>
                      </table>
                    </td>
                  </tr>
                </table>
              {% endfor %}

            {% if line.discount_allocations %}
              {% for discount_allocation in line.discount_allocations %}
                {% if discount_allocation.discount_application.target_selection != 'all' %}
                  <p>
                    <span class="order-list__item-discount-allocation">
