store_receipt.bodyHtml:
{% assign buyer_email_rtl = false %}{% if locale_direction == 'rtl' %}{% assign buyer_email_rtl = true %}{% endif %}{% capture email_title %}
  Thank you for your order!
{% endcapture %}
{% assign delivery_method_types = delivery_agreements | map: 'delivery_method_type' | uniq %}
{% if delivery_method_types.size > 1 %}
  {% assign has_split_cart = true %}
{% else %}
  {% assign has_split_cart = false %}
{% endif %}
{% assign has_pickup_delivery = false %}
{% assign estimated_pickup_date = '' %}
{% if delivery_method == 'pick-up' %}
  {% assign has_pickup_delivery = true %}
{% endif %}
{% for delivery_agreement in delivery_agreements %}
  {% if delivery_agreement.delivery_method_type == 'pick-up' %}
    {% assign has_pickup_delivery = true %}
    {% if estimated_pickup_date == blank and delivery_agreement.estimated_delivery_date %}
      {% assign estimated_pickup_date = delivery_agreement.estimated_delivery_date %}
    {% endif %}
  {% endif %}
{% endfor %}
<!DOCTYPE html>
<html lang="en"{% if buyer_email_rtl %} dir="rtl"{% endif %}>
  <head>
