          <span class="order-list__item-title">{% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ line_item.title_without_variant }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}&nbsp;&times;&nbsp;{% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ line_display }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}</span><br/>

          {% if line_item.variant and line_item.variant.title != 'Default Title' %}
            <span class="order-list__item-variant">{% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ line_item.variant.title }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}</span><br/>
          {% endif %}

          {% for group in line_item.groups %}
            {% if group.deliverable? %}
              <span class="order-list__item-variant">For: {% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ group.display_title }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}</span>
            {% else %}
              <span class="order-list__item-variant">Part of: {% if buyer_email_rtl == true %}&rlm;&lrm;<span dir="auto" style="display: inline-block; unicode-bidi: isolate; font-size: inherit;">{% endif %}{{ group.display_title }}{% if buyer_email_rtl == true %}</span>&lrm;&rlm;{% endif %}</span>
            {% endif %}
            <br/>
          {% endfor %}

          {% if line_item.discount_allocations %}
            {% for discount_allocation in line_item.discount_allocations %}
