    .subtotal-line__title, .subtotal-line__title p { color: #4a3338 !important; font-size: 13px !important; }
    .subtotal-table--total td, .subtotal-table--total .subtotal-line__title p, .subtotal-table--total .subtotal-line__value { color: #551c25 !important; font-size: 16px !important; font-weight: normal !important; }
